INSERT INTO public.curriculum_courses (course_code, grade, term, subject_name, learning_area, course_type, hours, description) VALUES
  ('ว21103', 'ม.1', 2, 'เทคโนโลยี (การออกแบบและเทคโนโลยี)', 'วิทยาศาสตร์และเทคโนโลยี', 'รายวิชาพื้นฐาน', 20, 'ศึกษาแนวคิดหลักของเทคโนโลยีในชีวิตประจำวัน วิเคราะห์สาเหตุหรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี ระบุปัญหาหรือความต้องการในชีวิตประจำวัน รวบรวม วิเคราะห์ข้อมูล แนวคิดที่เกี่ยวข้องกับปัญหา การออกแบบวิธีการแก้ปัญหา ตัดสินใจเลือกข้อมูลที่จำเป็น นำเสนอแนวทางการแก้ปัญหาให้ผู้อื่นเข้าใจ วางแผน ดำเนินการแก้ปัญหา ด้วยการทดสอบ ประเมินผล ระบุข้อบกพร่องที่เกิดขึ้น พร้อมทั้งหาแนวทางปรับปรุงแก้ไข และนำเสนอผลการแก้ปัญหา เลือกใช้วัสดุ อุปกรณ์ เครื่องมือ กลไก ไฟฟ้า หรืออิเล็กทรอนิกส์เพื่อแก้ปัญหาได้อย่างถูกต้อง เหมาะสมและปลอดภัย โดยอาศัยรูปแบบการจัดการเรียนรู้โดยใช้ปัญหาเป็นฐาน ( Problem - Based Learning ) และรูปแบบการจัดการเรียนรู้แบบสืบทอดความรู้ ( 5Es Instructional Model ) เน้นในผู้เรียนได้ลงมือปฏิบัติ ฝึกทักษะการคิด เผชิญสถานการณ์การแก้ปัญหา วางแผนการเรียนรู้ และนำเสนอผ่านการทำกิจกรรมโครงงาน เพื่อให้ผู้เรียนมีความรู้ ความเข้าใจความสัมพันธ์ของความรู้วิทยาศาสตร์ที่มีผลต่อการพัฒนาเทคโนโลยีประเภทต่าง ๆ และการพัฒนาเทคโนโลยีที่ส่งผลให้มีการคิดค้นความรู้ทางวิทยาศาสตร์ที่ก้าวหน้าผลของเทคโนโลยีต่อชีวิต สังคมและสิ่งแวดล้อม ตลอดจนนำความรู้ความเข้าใจในกลุ่มสาระการเรียนรู้วิทยาศาสตร์และเทคโนโลยีไปใช้ให้เกิดประโยชน์ต่อสังคม และการดำรงชีวิต จนสามารถพัฒนากระบวนการคิดและจินตนาการ ความสามารถในการแก้ปัญหาและการจัดทักษะในการสื่อสาร ความสามารถในการตัดสินใจ เป็นผู้ที่มีจิตวิทยาศาสตร์ มีคุณธรรม จริยธรรม ค่านิยมในการใช้วิทยาศาสตร์และเทคโนโลยี อย่างสร้างสรรค์'),
  ('ว22103', 'ม.2', 2, 'เทคโนโลยี (การออกแบบและเทคโนโลยี)', 'วิทยาศาสตร์และเทคโนโลยี', 'รายวิชาพื้นฐาน', 20, 'ศึกษาสาเหตุหรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี ผลกระทบจากการเปลี่ยนแปลงเทคโนโลยีต่อมนุษย์ และสังคม ผลกระทบจากการเปลี่ยนแปลงต่อเศรษฐกิจ ผลกระทบจากการเปลี่ยนแปลงต่อสิ่งแวดล้อม ประเภทของวัสดุ อุปกรณ์ เพื่อให้สามารถสร้างชิ้นงานได้ตรงกับความต้องการ มีความปลอดภัยและใช้ทรัพยากรได้อย่างคุ้มค่า เครื่องกลในการสร้างชิ้นงาน ได้แก่ รอก คาน ล้อและเพลา พื้นเอียง ลิ่ม และสกรู เครื่องมือในการสร้างชิ้นงาน เครื่องมือสำหรับการวัด เครื่องมือสำหรับการตัด เครื่องมือสำหรับยึดติดเครื่องมือสำหรับเจาะ เสียงและอุปกรณ์ที่ทำให้เกิดเสียง ไฟฟ้า วงจรไฟฟ้าอย่างง่าย การต่อตัวต้านทานความสัมพันธ์ของกระบวนการทางวิทยาศาสตร์และวิศวกรรม แนวคิดกระบวนการทางวิทยาศาสตร์กระบวนการออกแบบเชิงวิศวกรรม การคิดเชิงออกแบบ แนวคิดหลักของการคิดเชิงออกแบบ ถอดความคิดกระบวนการคิดเชิงออกแบบของพระบาทสมเด็จพระบรมชนกาธิเบศร มหาภูมิพลอดุลยเดชมหาราช บรมนาถบพิตร (รัชกาลที่ 9) โดยอาศัยรูปแบบการจัดการเรียนรู้โดยใช้ปัญหาเป็นฐาน ( Problem - Based Learning ) และรูปแบบการจัดการเรียนรู้แบบสืบทอดความรู้ ( 5Es Instructional Model ) เน้นในผู้เรียนได้ลงมือปฏิบัติ ฝึกทักษะการคิด เผชิญสถานการณ์การแก้ปัญหา วางแผนการเรียนรู้ และนำเสนอผ่านการทำกิจกรรมโครงงาน เพื่อให้ผู้เรียนมีความรู้ ความเข้าใจความสัมพันธ์ของความรู้วิทยาศาสตร์ที่มีผลต่อการพัฒนาเทคโนโลยีประเภทต่าง ๆ และการพัฒนาเทคโนโลยีที่ส่งผลให้มีการคิดค้นความรู้ทางวิทยาศาสตร์ที่ก้าวหน้าผลของเทคโนโลยีต่อชีวิต สังคมและสิ่งแวดล้อม ตลอดจนนำความรู้ความเข้าใจในกลุ่มสาระการเรียนรู้วิทยาศาสตร์และเทคโนโลยีไปใช้ให้เกิดประโยชน์ต่อสังคม และการดำรงชีวิต จนสามารถพัฒนากระบวนการคิดและจินตนาการ ความสามารถในการแก้ปัญหาและการจัดทักษะในการสื่อสาร ความสามารถในการตัดสินใจ เป็นผู้ที่มีจิตวิทยาศาสตร์ มีคุณธรรม จริยธรรม ค่านิยมในการใช้วิทยาศาสตร์และเทคโนโลยีอย่างสร้างสรรค์'),
  ('ว23103', 'ม.3', 2, 'เทคโนโลยี (การออกแบบและเทคโนโลยี)', 'วิทยาศาสตร์และเทคโนโลยี', 'รายวิชาพื้นฐาน', 20, 'ศึกษาสาเหตุหรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี และผลกระทบต่อมนุษย์ สังคมเศรษฐกิจ สิ่งแวดล้อม และอาชีพในชุน เพื่อสำรวจและระบุปัญหาที่เกิดขึ้นได้ตรงตามความจริง กระบวนการแก้ปัญหาโดยใช้ความรู้ทางวิทยาศาสตร์และศาสตร์อื่น ๆ ร่วมกัน ความรู้ความเข้าใจเกี่ยวกับประเภทและสมบัติของวัสดุต่าง ๆ เช่น ไม้ เหล็ก พลาสติก ยางพารา เครื่องมือในการสร้างชิ้นงาน เช่น ค้อน ประแจ สว่านคีมประเภทต่าง ๆ เพื่อให้สามารถตัดสินใจเลือกแนวทางในการออกแบบการแก้ปัญหาได้อย่างเหมาะสม โดยอาศัยรูปแบบการสอนแบบสืบเสาะหาความรู้ ( 5Es Instructional Model ) วิธีการสอนโดยเน้นรูปแบบการสอนแบบใช้ปัญหาเป็นฐาน โครงงานเป็นฐาน ( Problem - Based Learning ) และรูปแบบการสอนแบบใช้โครงงานเป็นฐาน ( Project - Based Learning ) เพื่อเน้นให้ผู้เรียนได้ลงมือปฏิบัติ ฝึกทักษะการคิด เผชิญสถานการณ์การแก้ปัญหา วางแผนการเรียนรู้ ตรวจสอบการเรียนรู้ และสร้างองค์ความรู้ใหม่ด้วยตนเองผ่านกระบวนการคิด และปฏิบัติโดยใช้กระบวนการทางวิทยาศาสตร์ เพื่อให้ผู้เรียนมีความรู้ความเข้าใจ มีทักษะเกี่ยวกับการใช้ความรู้ด้านวิทยาศาสตร์และศาสตร์อื่น ๆ ในการออกแบบและพัฒนาเทคโนโลยีด้านต่าง ๆ ที่สามารถนำใช้ในชีวิตจริงได้อย่างมีประสิทธิภาพ และเกิดประโยชน์ต่อสังคมและการดำรงชีวิต จนสามารถพัฒนากระบวนการคิดและจินตนาการ ความสามารถในการแก้ปัญหาและการจัดการทักษะในการสื่อสาร และความสามารถในการตัดสินใจ และเป็นผู้ที่มีจิตวิทยาศาสตร์มีคุณธรรม จริยธรรม และค่านิยมในการใช้วิทยาศาสตร์และเทคโนโลยีอย่างสร้างสรรค์')
INSERT INTO public.curriculum_indicators (indicator_code, grade, standard, description) VALUES
  ('ว 4.1 ม.1/1', 'ม.1', 'ว 4.1', 'อธิบายแนวคิดหลักของเทคโนโลยีในชีวิตประจำวันและวิเคราะห์สาเหตุหรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี'),
  ('ว 4.1 ม.1/2', 'ม.1', 'ว 4.1', 'ระบุปัญหาหรือความต้องการในชีวิตประจำวันรวบรวม วิเคราะห์ข้อมูลและแนวคิดที่เกี่ยวข้องกับปัญหา'),
  ('ว 4.1 ม.1/3', 'ม.1', 'ว 4.1', 'ออกแบบวิธีการแก้ปัญหา โดยวิเคราะห์เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็นนำเสนอแนวทางการแก้ปัญหาให้ผู้อื่นเข้าใจวางแผนและดำเนินการแก้ปัญหา'),
  ('ว 4.1 ม.1/4', 'ม.1', 'ว 4.1', 'ทดสอบ ประเมินผล และระบุข้อบกพร่องที่เกิดขึ้น พร้อมทั้งหาแนวทางการปรับปรุงแก้ไขและนำเสนอผลการแก้ปัญหา'),
  ('ว 4.1 ม.1/5', 'ม.1', 'ว 4.1', 'ใช้ความรู้และทักษะเกี่ยวกับวัสดุ อุปกรณ์เครื่องมือ กลไก ไฟฟ้า หรืออิเล็กทรอนิกส์เพื่อแก้ปัญหาได้อย่างถูกต้อง เหมาะสมและปลอดภัย'),
  ('ว 4.1 ม.2/1', 'ม.2', 'ว 4.1', 'คาดการณ์แนวโน้มเทคโนโลยีที่จะเกิดขึ้นโดยพิจารณาจากสาเหตุหรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี และวิเคราะห์เปรียบเทียบ ตัดสินใจเลือกใช้เทคโนโลยีโดยคำนึงถึงผลกระทบที่เกิดขึ้นต่อชีวิต สังคมและสิ่งแวดล้อม'),
  ('ว 4.1 ม.2/2', 'ม.2', 'ว 4.1', 'ระบุปัญหาหรือความต้องการในชุมชนหรือท้องถิ่น สรุปกรอบของปัญหา รวบรวม วิเคราะห์ข้อมูลและแนวคิดที่เกี่ยวข้องกับปัญหา'),
  ('ว 4.1 ม.2/3', 'ม.2', 'ว 4.1', 'ออกแบบวิธีการแก้ปัญหา โดยวิเคราะห์เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็นภายใต้เงื่อนไขและทรัพยากรที่มีอยู่ นำเสนอแนวทางการแก้ปัญหาให้ผู้อื่นเข้าใจ วางแผนขั้นตอนการทำงานและดำเนินการแก้ปัญหาอย่างเป็นขั้นตอน'),
  ('ว 4.1 ม.2/4', 'ม.2', 'ว 4.1', 'ทดสอบ ประเมินผล และอธิบายปัญหาหรือข้อบกพร่องที่เกิดขึ้น ภายใต้กรอบเงื่อนไขพร้อมทั้งหาแนวทางการปรับปรุงแก้ไข และนำเสนอผลการแก้ปัญหา'),
  ('ว 4.1 ม.2/5', 'ม.2', 'ว 4.1', 'ใช้ความรู้ และทักษะเกี่ยวกับวัสดุ อุปกรณ์เครื่องมือ กลไก ไฟฟ้า และอิเล็กทรอนิกส์เพื่อแก้ปัญหาหรือพัฒนางานได้อย่างถูกต้องเหมาะสม และปลอดภัย'),
  ('ว 4.1 ม.3/1', 'ม.3', 'ว 4.1', 'วิเคราะห์สาเหตุ หรือปัจจัยที่ส่งผลต่อการเปลี่ยนแปลงของเทคโนโลยี และความสัมพันธ์ของเทคโนโลยีกับศาสตร์อื่น โดยเฉพาะวิทยาศาสตร์ หรือคณิตศาสตร์ เพื่อเป็นแนวทางการแก้ปัญหาหรือพัฒนางาน'),
  ('ว 4.1 ม.3/2', 'ม.3', 'ว 4.1', 'ระบุปัญหาหรือความต้องการของชุมชนหรือท้องถิ่น เพื่อพัฒนางานอาชีพ สรุปกรอบของปัญหา รวบรวม วิเคราะห์ข้อมูลและแนวคิดที่เกี่ยวข้องกับปัญหา โดยคำนึงถึงความถูกต้องด้านทรัพย์สินทางปัญญา'),
  ('ว 4.1 ม.3/3', 'ม.3', 'ว 4.1', 'ออกแบบวิธีการแก้ปัญหา โดยวิเคราะห์เปรียบเทียบ และตัดสินใจเลือกข้อมูลที่จำเป็นภายใต้เงื่อนไขและทรัพยากรที่มีอยู่ นำเสนอแนวทางการแก้ปัญหาให้ผู้อื่นเข้าใจด้วยเทคนิคหรือวิธีการที่หลากหลาย วางแผนขั้นตอนการทำงานและดำเนินการแก้ปัญหาอย่างเป็นขั้นตอน'),
  ('ว 4.1 ม.3/4', 'ม.3', 'ว 4.1', 'ทดสอบ ประเมินผล วิเคราะห์ และให้เหตุผลของปัญหาหรือข้อบกพร่องที่เกิดขึ้นภายใต้กรอบเงื่อนไข พร้อมทั้งหาแนวทางการปรับปรุงแก้ไข และนำเสนอผลการแก้ปัญหา'),
  ('ว 4.1 ม.3/5', 'ม.3', 'ว 4.1', 'ใช้ความรู้ และทักษะเกี่ยวกับวัสดุ อุปกรณ์เครื่องมือ กลไก ไฟฟ้าและอิเล็กทรอนิกส์ให้ถูกต้องกับลักษณะของงาน และปลอดภัยเพื่อแก้ปัญหาหรือพัฒนางาน')
INSERT INTO public.curriculum_units (course_code, unit_no, seq, name, hours, essence) VALUES
  ('ว21103', 1, 1, 'เทคโนโลยีกับมนุษย์', 4, 'เทคโนโลยี เป็นสิ่งที่มนุษย์สร้างหรือพัฒนาขึ้น ซึ่งอาจเป็นได้ทั้งชิ้นงานหรือวิธีการเพื่อใช้แก้ปัญหา สนองความต้องการ หรือเพิ่มความสามารถในการทำงานของมนุษย์ เทคโนโลยีมีการเปลี่ยนแปลงตลอดเวลาตั้งแต่อดีตจนถึงปัจจุบัน ซึ่งมีสาเหตุหรือปัจจัยมาจากหลายด้าน เช่นปัญหา ความต้องการ ความก้าวหน้าของศาสตร์ต่าง ๆ เศรษฐกิจ สังคม ระบบทางเทคโนโลยี เป็นกลุ่มของส่วนต่าง ๆ ตั้งแต่สองส่วนขึ้นไปประกอบเข้าด้วยกันและทำงานร่วมกันเพื่อให้บรรลุวัตถุประสงค์ โดยในการทำงานของระบบทางเทคโนโลยีประกอบไปด้วย ตัวป้อน ( Input) กระบวนการ ( Process) และผลผลิต ( Output) ที่สัมพันธ์กันนอกจากนี้ระบบทางเทคโนโลยีอาจมีข้อมูลย้อนกลับ ( Feedback) เพื่อใช้ปรับปรุงการทำงานได้ตามวัตถุประสงค์ซึ่งการวิเคราะห์ระบบทางเทคโนโลยีช่วยให้เข้าใจองค์ประกอบและการทำงานของเทคโนโลยี รวมถึงสามารถปรับปรุงให้เทคโนโลยีทำงานได้ตามต้องการ ปัญหาหรือความต้องการในชีวิตประจำวันของมนุษย์พบได้จากหลายสาเหตุขึ้นอยู่กับสถานการณ์ที่มนุษย์แต่ละคนจะประสบเช่น ปัญหาทางด้านการเกษตรปัญหาจากการขาดแคลนอาหาร ดังนั้น การแก้ปัญหาผู้ที่ทำหน้าที่ในการแก้ปัญหาจำเป็นต้องสืบค้น รวบรวมข้อมูลความรู้จากศาสตร์ต่าง ๆ ที่เกี่ยวข้อง เพื่อนำไปสู่การออกแบบแนวทางการแก้ปัญหา ที่มีประสิทธิภาพและส่งผลกระทบในด้านลบต่อสิ่งต่าง ๆ เช่น สภาพแวดล้อมทรัพยากร วิถีชีวิตของมนุษย์'),
  ('ว21103', 2, 2, 'กระบวนการออกแบบเชิงวิศวกรรม', 5, 'ปัญหาหรือความต้องการในชีวิตประจำวันพบได้จากหลายบริบทขึ้นกับสถานการณ์ที่ประสบ เช่นการเกษตร อาหาร ดังนั้นการแก้ไขปัญหาผ่านกระบวนการเทคโนโลยีจำเป็นต้องสืบค้น รวบรวมข้อมูลความรู้จากศาตร์ต่าง ๆ ที่เกี่ยวข้อง เพื่อนำไปสู่การออกแบบแนวทางการแก้ไขปัญหาโดยเริ่มจากการวิเคราะห์ เปรียบเทียบและตัดสินใจเลืกข้อมูลที่จำเป็น โดยคำนึงถึงเงื่อนไขและทรัพยากรที่มีอยู่ ช่วยให้ได้แนวทางการแก้ไขปัญหาที่เหมาะสมแล้วดำเนินการออกแบบแนวทางการแก้ไขปัญหาทำได้หลากหลายวิธี เช่น การร่างภาพ การเขียนแผน การเขียนผังงานพร้อมทั้งกำหนดขั้นตอนและระยะเวลาในการทำงานก่อนดำเนินการแก้ไขปัญหาจะช่วยให้ทำงานสำเร็จได้ตามเป้าหมาย การทดลองและประเมินผลเป็นการตรวจสอบชิ้นงานหรือวิธีการว่าสารถแก้ไขปัญหาได้ตามวัตถุประสงค์เพื่อหาข้อบกพร่อง และดำเนินการปรับปรุงให้สามารถแก้ไขปัญหาได้ และจะสมบูรณ์เมื่อนำเสนอผลงานเป็นการถ่ายทอดแนวคิดเพื่อให้ผู้อื่นเข้าใจเกี่ยวกับกระบวนการทำงานและชิ้นงานหรือวิธีการที่ได้ ซึ่งสามารถทำได้หลายวิธี เช่นการเขียนรายงาน การทำแผ่นนำเสนองาน ปัญหาหรือความต้องการในชีวิตประจำวันของมนุษย์พบได้จากหลายสาเหตุขึ้นอยู่กับสถานการณ์ที่มนุษย์แต่ละคนจะประสบ เช่น ปัญหาทางด้านการเกษตร ปัญหาจากการขาดแคลนอาหาร ดังนั้นผู้ที่ทำหน้าที่ในการแก้ปัญหาจำเป็นต้องสืบค้นรวบรวมข้อมูลความรู้จากศาสตร์ต่าง ๆ ที่เกี่ยวข้องวิวัฒนาการของเทคโนโลยี เพื่อนำไปสู่การออกแบบแนวทางการแก้ปัญหาที่มีประสิทธิภาพและส่งผลกระทบในด้านลบต่อสิ่งต่าง ๆ เช่น สภาพแวดล้อมทรัพยากรวิถีชีวิตของมนุษย์'),
  ('ว21103', 3, 3, 'ผลงานออกแบบเทคโนโลยี', 11, 'การสร้างผลงานออกแบบเทคโนโลยีควรคำนึงถึงวัสดุแต่ละประเภทมีสมบัติแตกต่างกัน เช่น ไม้ โลหะ พลาสติก จึงต้องมีการวิเคราะห์สมบัติเพื่อเลือกใช้ให้เหมาะสมกับลักษณะของงาน และการสร้างชิ้นงานอาจใช้ความรู้ เรื่อง กลไกไฟฟ้า อิเล็กทรอนิกส์ เช่น LED บัซเซอร์มอเตอร์ วงจรไฟฟ้า ดังนั้น อุปกรณ์และเครื่องมือในการสร้างชื้นงาน หรือพัฒนาวิธีการมีหลายประเภท ต้องเลือกใช้วัสดุให้ถูกต้องเหมาะสม และปลอดภัยรวมทั้งรู้จักเก็บรักษา สามารถศึกษากรณีตัวอย่าง เพื่อพัฒนาโครงงาน ประดิษฐ์อุปกรณ์ที่ช่วยอำนวยความสะดวก แก้ไขปัญหาที่เกิดขึ้นในการดำรงชีวิต วิเคราะห์และให้เหตุผลของปัญหาหรือข้อบกพร่องที่เกิดขึ้นภายใต้กรอบเงื่อนไขหาแนวทางการปรับปรุงแก้ไข และนำเสนอผลการแก้ไข พร้อมทั้งเสนอแนวทางการพัฒนาต่อยอด การใช้เทคโนโลยีมาแก้ปัญหาหรือความต้องการผ่านการพัฒนาโครงงานตามกระบวนการออกแบบเชิงวิศวกรรมทำให้เกิดทักษะสู่การปฏิบัติ เพื่อสร้างสรรค์ชิ้นงาน ด้วยการศึกษากรณีตัวอย่าง หมวกจักรยานอัจฉริยะ และหุ่นยนต์ปากกา ซึ่งเป็นการศึกษาเรื่องราวด้านวิทยาศาสตร์และเทคโนโลยี ผ่านทางโครงงานประเภทประดิษฐ์ เป็นการประยุกต์ทฤษฎี หรือหลักการทางวิทยาศาสตร์หรือด้านอื่น ๆ มาประดิษฐ์ของเล่น เครื่องมือ เครื่องใช้หรืออุปกรณ์เพื่อประโยชน์ใช้สอยต่าง ๆ ซึ่งอาจจะเป็นสิ่งประดิษฐ์ใหม่ หรือปรับปรุงเปลี่ยนแปลงของเดิมให้มีประสิทธิภาพมากยิ่งขึ้น หรือการสร้างแบบจำลองเพื่ออธิบายแนวคิดต่าง ๆ'),
  ('ว22103', 1, 1, 'เทคโนโลยีกับชีวิตประจำวัน', 4, 'เทคโนโลยีเกิดขึ้นและเปลี่ยนแปลงได้ก็ต่อเมื่อมีปัจจัยจากด้านต่าง ๆ เช่น ความรู้จากวิทยาศาสตร์ คณิตศาสตร์สังคมศาสตร์ และศาสตร์อื่น ๆ ส่งผลให้เกิดการเปลี่ยนแปลงเชิงเศรษฐกิจและสังคมไปทั่วโลก มีการพัฒนาเทคโนโลยีใหม่ให้ก้าวหน้าอย่างรวดเร็ว รวมถึงประเทศต่าง ๆ ได้พัฒนานวัตกรรมและนำมาใช้ในการเพิ่มมูลค่าในการผลิตและเพิ่มประสิทธิภาพ เพื่อสร้างโอกาสในการแข่งขันทางธุรกิจ ส่วนใหญ่เทคโนโลยีเป็นเครื่องมือหรือเป็นตัวช่วยในการอำนวยความสะดวกสบายในชีวิตประจำวันเช่น การใช้อินเทอร์เน็ตติดต่อสื่อสารกับผู้อื่นได้อย่างรวดเร็ว เทคโนโลยีเข้ามามีบทบาทในชีวิตมนุษย์ในหลายด้าน จึงมีการพัฒนาและสร้างเทคโนโลยีให้เจริญก้าวหน้าตลอดเวลา โดยเทคโนโลยีเป็นตัวช่วยอำนวยความสะดวกให้แก่มนุษย์ เช่นด้านสื่อสาร การศึกษา การแพทย์การเกษตร แต่ถ้ามนุษย์นำเทคโนโลยีไปใช้ในทางที่ไม่ดีก็อาจจะทำให้เกิดผลกระทบต่อการใช้ชีวิต เช่น การสร้างบัญชีสังคมออนไลน์เพื่อหลอกขายสินค้า การโจรกรรมข้อมูล ซึ่งการเปลี่ยนแปลงของเทคโนโลยีส่งผลกระทบ 3 ด้าน คือ ด้านมนุษย์และสังคม ด้านเศรษฐกิจ และด้านสิ่งแวดล้อม'),
  ('ว22103', 2, 2, 'วัสดุ อุปกรณ์และเครื่องมือทางเทคโนโลยี', 8, 'ปัจจุบันวิทยาศาสตร์และเทคโนโลยีพัฒนาและก้าวหน้าอย่างรวดเร็ว จึงได้มีการนำความรู้เหล่านี้มาพัฒนาและปรับปรุงวัสดุต่าง ๆ เพื่อตอบสนองต่อความต้องการที่หลากหลาย โดยผ่านสร้างเครื่องมือหรือชิ้นงาน ความรู้เกี่ยวกับวัสดุ อุปกรณ์ เครื่องมือกลไก เสียง แสง ไฟฟ้า และอุปกรณ์อิเล็กทรอนิกส์เป็นสิ่งสำคัญ ซึ่งจะช่วยทำให้สร้างชิ้นงานได้เหมาะสมและปลอดภัย'),
  ('ว22103', 3, 3, 'กระบวนการออกแบบเชิงวิศวกรรม', 4, 'ในปัจจุบันวิวัฒนาการของมนุษย์พัฒนาไปอย่างรวดเร็วมนุษย์จึงได้นำกระบวนการทางวิทยาศาสตร์เข้ามาช่วยแก้ปัญหาแต่มนุษย์ก็ไม่หยุดที่จะเรียนรู้สิ่งใหม่ ๆ และยังคงมีการพัฒนาเทคโนโลยี และนวัตกรรมอย่างต่อเนื่อง โดยมนุษย์ได้คิดค้นหลักการของกระบวนการทางวิศวกรรมศาสตร์มา เพื่อตอบสนองความต้องการของมนุษย์ที่จะคิดค้นและประดิษฐ์สิ่งต่าง ๆ มาทำให้มนุษย์ได้ใช้ชีวิตอย่างสะดวกสบายมากขึ้น เมื่อเรามองไปรอบ ๆ ตัวของเราก็จะพบเห็นสิ่งปลูกสร้าง สิ่งอำนวยความสะดวก ที่จะช่วยให้มนุษย์ดำเนินชีวิตได้สะดวกสบายสิ่งเหล่านี้เกิดจากการที่มนุษย์คิดค้นและทำการทดลองทฤษฎีต่าง ๆ จนได้ข้อสรุปแนวคิดที่แน่ชัด มนุษย์จึงเริ่มคิดค้นและประดิษฐ์สิ่งต่าง ๆ โดยจะผ่านการวางแผน รวบรวมองค์ความรู้การออกแบบ ทดสอบ ประเมินผลและนำเสนอ ซึ่งกระบวนการทั้งหมดเหล่านี้เรียกว่ากระบวนการออกแบบเชิงวิศวกรรม'),
  ('ว22103', 4, 4, 'การคิดเชิงออกแบบ', 4, 'การคิดเชิงออกแบบเป็นแนวคิดที่ใช้ในการแก้ปัญหา โดยยึดเอาคนหรือประสบการณ์ผู้ใช้เป็นศูนย์กลาง และร่วมกันค้นคิดวิธีการแก้ปัญหาร่วมกันของทีมงานอย่างสร้างสรรค์ ทำให้ต้นแบบที่ผลิตขึ้นมาเป็นเทคโนโลยีที่มีความที่มีข้อผิดพลาดน้อย และเทคโนโลยีนั้นมีมูลค่าที่สูงขึ้น ซึ่งจะเป็นการแก้ปัญหาด้วยการเน้นทำความเข้าใจว่าคนต้องการอะไร แทนที่วิธีการแบบเดิมที่มักเริ่มต้นจาก “ ปัญหา ” การคิดเชิงออกแบบเป็นแนวคิดที่ใช้ในการแก้ปัญหา โดยยึดเอาคนหรือประสบการณ์ผู้ใช้เป็นศูนย์กลาง ซึ่งโครงการในพระราชดำริของพระบาทสมเด็จพระปรมินทรมหาภูมิพลอดุลยเดชทุกโครงการ ไม่ได้ริเริ่มจากการค้นคว้าหรือวิจัยในห้องทำงานแต่เริ่มจากการลงพื้นที่เก็บประสบการณ์ของประชาชนที่ต้องการความช่วยเหลือ'),
  ('ว23103', 1, 1, 'เทคโนโลยีกับการเปลี่ยนแปลง', 5, 'ความต้องการของมนุษย์หมายถึงสภาวะที่มนุษย์อยากได้รับสิ่งต่าง ๆ เพื่อสนองความต้องการหรือการแก้ปัญหา เมื่อมนุษย์เกิดความต้องการ จึงเกิดการแสวงหาและสร้างสิ่งต่าง ๆ เพื่อตอบสนองความต้องการนั้นเมื่อความต้องการได้รับการตอบสนองแล้ว ก็มักจะมีความต้องการใหม่เกิดขึ้นตามมาเสมอดังนั้น ความต้องการของมนุษย์จึงเป็นสิ่งที่ไม่มีที่สิ้นสุดและเปลี่ยนแปลงไปตามกาลเวลาความต้องการของมนุษย์และการพัฒนาเทคโนโลยีมีความสัมพันธ์ที่เชื่อมโยงกัน เมื่อมนุษย์มีความต้องการที่เพิ่มขึ้น เทคโนโลยีจึงถูกพัฒนาอย่างต่อเนื่องเพื่อรองรับและตอบสนองความต้องการเหล่านั้นได้อย่างสมบูรณ์และยั่งยืน ความต้องการเหล่านี้ส่งผลให้เกิดการเปลี่ยนแปลงในสังคมหลากหลายด้าน ไม่ว่าจะเป็นด้านเศรษฐกิจ ที่มีการผลิตและแลกเปลี่ยนสินค้าใหม่ ๆ ด้านสังคมเกิดการเปลี่ยนแปลงวิถีชีวิต ความสัมพันธ์ และโครงสร้างของชุมชน ด้านวัฒนธรรมเกิดการผสมผสานและพัฒนาค่านิยมใหม่รวมถึง ด้านสิ่งแวดล้อมที่มีการใช้ทรัพยากรเพื่อสนองความต้องการของมนุษย์ การเปลี่ยนแปลงเหล่านี้ผลักดันให้เกิดการพัฒนาเทคโนโลยี ซึ่งหมายถึงการนำองค์ความรู้จากศาสตร์ต่าง ๆ เช่นวิทยาศาสตร์และคณิตศาสตร์ มาใช้ในการแก้ปัญหาและสร้างนวัตกรรม เทคโนโลยีช่วยให้มนุษย์สามารถตอบสนองความต้องการได้อย่างมีประสิทธิภาพซึ่งส่งผลกระทบต่อตนเองและชุมชน เช่น การนำเทคโนโลยีขั้นสูงมาใช้ในทุกภาคส่วนที่เกี่ยวกับเทคโนโลยีดิจิทัลเทคโนโลยีชีวภาพ และนาโนเทคโนโลยี เทคโนโลยีที่ได้รับการพัฒนาจากอดีตจนถึงปัจจุบัน ซึ่งถือเป็นเครื่องมือสำคัญในการศึกษาค้นคว้า สร้างองค์ความรู้และนวัตกรรมใหม่ ๆ อย่างสร้างสรรค์ทำให้เกิดนวัตกรรมที่นำไปใช้ตอบสนองความต้องการของสังคมและรองรับการเปลี่ยนแปลงในการประกอบอาชีพได้อย่างมีประสิทธิภาพ โดยเฉพาะอย่างยิ่งในปั จจุ บั น มี การมุ่ งเน้ นการส่ งเสริ มการพัฒนาเทคโนโลยีพื้นฐานที่สำคัญ 4 ด้าน ดังนี้ 1. เทคโนโลยี ชี วภาพ เพื่ อการแพทย์ เกษตรกรรม และสิ่งแวดล้อม 2. นาโนเทคโนโลยี เพื่ อพัฒนาวัสดุและผลิตภัณฑ์ในระดับนาโนที่มีประสิทธิภาพสูง 3. เทคโนโลยีวัสดุศาสตร์ พลังงานและสิ่งแวดล้อม เพื่อสร้างวัสดุและแหล่งพลังงานที่เป็นมิตรต่อสิ่งแวดล้อม 4. เทคโนโลยี สารสนเทศ การสื่อสาร และดิจิทัล เพื่อรองรับการสื่ อสาร การทำงาน และการใช้ชีวิตในยุคดิจิทัลการพัฒนาเทคโนโลยีในทั้ง 4 ด้านนี้ จึงมีความสำคัญในการยกระดับคุณภาพชีวิต สร้างความรู้ ใหม่และสนับสนุนการพัฒนาเศรษฐกิจ สังคม และสิ่งแวดล้อมอย่างยั่งยืน'),
  ('ว23103', 2, 2, 'เทคโนโลยีกับการแก้ปัญหา', 7, 'การเก็บรวบรวมข้อมูลทางกายภาพ สังคม เศรษฐกิจวัฒนธรรม และสิ่งแวดล้อม เพื่อระบุความต้องการและปัญหาของชุมชนอย่างเป็นระบบ ด้าวการใช้เอกสาร ฐานข้อมูล แบบสอบถามและการสัมภาษณ์ผู้คนในชุมชนจึงช่วยจำกัดขอบเขตและสาเหตุของปัญหาได้ชัดเจน โดยคำนึงถึงผลกระทบด้านเศรษฐกิจ สังคมวัฒนธรรม และสิ่งแวดล้อม เพื่อทำการประมวลผลด้วยเครื่องมือดิจิทัล เช่น ซอฟต์แวร์วิเคราะห์ข้อมูลและฐานข้อมูลออนไลน์แล้วทำการสังเคราะห์ผลลัพธ์ให้อยู่ในรูปแบบตัวเลข ข้อความรูปภาพ หรือภาพเคลื่อนไหว ทำให้ได้ข้อมูลที่ช่วยสนับสนุนการตัดสินใจอย่างมีประสิทธิภาพ พัฒนาความรู้พื้นฐานด้านการสร้างชิ้นงาน ด้วยการรู้สมบัติและวิธีใช้งานวัสดุโดยแบ่งเป็นโลหะและอโลหะ แต่ละประเภทมีสมบัติแตกต่างกัน จึงต้องเลือกวัสดุให้สอดคล้องกับวัตถุประสงค์การนำไปใช้งาน โดยคำนึงถึงต้นทุนในการดำเนินงาน เรียนรู้วิธีการบำรุงรักษาเครื่องมือและอุปกรณ์ช่างพื้นฐานเช่น คีม ไขควง สว่าน และเครื่องมือวัดไฟฟ้า โดยฝึกเลือกเครื่องมือให้เหมาะกับลักษณะงานและความปลอดภัย พร้อมทำการบำรุงรักษาตามกำหนดอย่างสม่ำเสมอ เพื่อยืดอายุการใช้งานและรักษาประสิทธิภาพ เข้าใจและประยุกต์ใช้หลักการของกลไกพื้นฐาน เช่นรอก เฟือง สปริง วงจรไฟฟ้า ทำให้ผู้เรียนเข้าใจกระบวนการนำไปใช้สร้างระบบกลไกและอิเล็กทรอนิกส์ เพื่อออกแบบชิ้นงานหรือวิธีการที่มีประสิทธิภาพ ปลอดภัย และคำนึงถึงผลกระทบต่อชุมชน'),
  ('ว23103', 3, 3, 'การแก้ปัญหาในชุมชนด้วยกระบวนการออกแบบเชิงวิศวกรรม', 8, 'กระบวนการออกแบบเชิงวิศวกรรมเป็นวิธีแก้ปัญหาหรือพัฒนาชิ้นงานอย่างเป็นขั้นตอนภายใต้ข้อจำกัดทรัพยากรทั้งด้านเวลา งบประมาณ และวัสดุ โดยอาศัยความรู้ทางวิทยาศาสตร์คณิตศาสตร์ และศาสตร์อื่นๆ มาประกอบการตัดสินใจ คำนึงถึงผลกระทบและเข้าใจพัฒนาเทคโนโลยีที่มีการคุ้มครองทรัพย์สินทางปัญญา เพื่อสร้างทางเลือกในการแก้ปัญหาที่มีประสิทธิภาพ พร้อมทั้งพัฒนาทักษะและเจตคติในการแก้ปัญหาชุมชนอย่างยั่งยืน กระบวนการออกแบบเชิงวิศวกรรมมี 6 ขั้นตอน คือ 1. ระบุปัญหา กำหนดขอบเขตจั ดลำดั บความสำคั ญ และวิเคราะห์บริบทของปัญหา 2. รวบรวมข้อมูลและแนวคิดที่เกี่ ยวข้ องกั บปั ญหา สำรวจหลักการพื้ นฐาน เทคนิค และเทคโนโลยี หรื อนวั ตกรรม ที่เกี่ยวข้องกับปัญหา 3. ออกแบบวิ ธีการแก้ปัญหา : สร้ างและเปรี ยบเที ยบแนวทางแก้ไขหลายรูปแบบทั้ งเชิงทฤษฎีและเชิงปฏิบัติ 4. วางแผนและดำเนิ นการแก้ปัญหา วางแผนขั้นตอน การใช้ ทรั พยากร ทดลองสร้ างต้นแบบ หรือนำเทคโนโลยีมาประยุกต์ใช้ 5. ทดสอบ ประเมิ นผล และปรับปรุงแก้ไขวิธีการแก้ปัญหาหรื อชิ้ นงาน ทดลองใช้ งานวิเคราะห์ข้อดีและข้อจำกัด แล้วปรับแก้ไขชิ้นงานจนได้ผลลัพธ์ตามเกณฑ์ 6. นำเสนอวิธีการแก้ปัญหา ผลการแก้ ปั ญหา หรื อชิ้ นงานถ่ายทอดวิธีแก้ปัญหา ผลการทดลอง และแสดงชิ้นงาน ผ่านรายงาน แผ่ นพับ นิ ทรรศการหรือสื่อออนไลน์ สร้างความเข้มแข็งให้ชุมชนพึ่งพาตนเอง เข้าใจบริบทเฉพาะของพื้นที่ กระตุ้นให้เกิดการลงมือปฏิบัติจริงและสร้างเศรษฐกิจฐานรากโดยใช้ทรัพยากรท้องถิ่นเป็นเครื่องมือประกอบอาชีพ ฝึกทักษะสื่ อสาร การเลือกข้ อมูลสร้างทางเลือกการแก้ปัญหาฝึกใช้เทคโนโลยีจากการสืบค้นข้อมูลและสร้างต้นแบบ จากการทำโครงงานตามกระบวนการออกแบบเชิ งวิ ศวกรรมพัฒนาเทคโนโลยีและสร้างนวัตกรรมเพื่อแก้ปัญหาในชุมชนอย่างยั่งยืนเริ่ มจากการสำรวจและระบุปัญหาเพื่อกำหนดขอบเขตความต้องการของชุมชน ตามด้วยการรวบรวมข้อมูลทั้งทางวิทยาศาสตร์ คณิตศาสตร์ และศาสตร์ ที่ เกี่ ยวข้ อง จากนั้นออกแบบแนวทางแก้ไขโดยร่างภาพหรือผังงานเพื่อเปรียบเทียบทางเลือกต่าง ๆ ก่อนวางแผนและลงมือสร้างต้นแบบจริง นำต้นแบบไปทดสอบการแก้ปัญหาในชุมขน และถ่ายทอดผลงานเพื่อให้ผู้ฟังเข้าใจทั้งกระบวนการและผลลัพธ์จากการทำโครงงานช่วยให้เกิดความเข้าใจรอบด้านและสามารถนำไปต่อยอดสร้างนวัตกรรมเพื่ อพัฒนาชุมชนให้เข้มแข็งและยั่งยืนในอนาคตได้');
