ON CONFLICT (course_code) DO UPDATE SET grade = EXCLUDED.grade, term = EXCLUDED.term, subject_name = EXCLUDED.subject_name, learning_area = EXCLUDED.learning_area, course_type = EXCLUDED.course_type, hours = EXCLUDED.hours, description = EXCLUDED.description;

ON CONFLICT (indicator_code) DO NOTHING;

